//! Myelin FFI crate: stable C ABI plus UniFFI bindings.

#![deny(unsafe_op_in_unsafe_fn)]

pub mod capi;
mod runtime;
mod uniffi_api;

pub use capi::MYELIN_ABI_VERSION;
pub use runtime::{ChatMessage, Sampling, STUB_TOKEN_COUNT};
pub use uniffi_api::{abi_version, Engine, MyelinError, Session, TokenEvent, TokenSink};

